#include <stdio.h>
int main(void) {
    unsigned char x = 0x01;
    /* set bit 3 */
    printf("%d\n", x);
    return 0;
}

activity.solution:
#include <stdio.h>
int main(void) {
    unsigned char x = 0x01;
    x |= (1u << 3);
    printf("%d\n", x);
    return 0;
}

