activity.starter:
#include <stdio.h>
int main(void) {
    unsigned char x = 0xB5;
    int count = 0;
    /* loop */
    printf("%d\n", count);
    return 0;
}

activity.solution:
#include <stdio.h>
int main(void) {
    unsigned char x = 0xB5;
    int count = 0;
    while (x) {
        count += x & 1;
        x >>= 1;
    }
    printf("%d\n", count);
    return 0;
}

