activity.solution:
#include <stdio.h>
int main(void) {
    int buf[4] = {0, 0, 0, 0};
    int head = 0, sum = 0;
    for (int v = 10; v <= 15; v++) {
        buf[head] = v;
        head = (head + 1) % 4;
    }
    for (int i = 0; i < 4; i++) sum += buf[i];
    printf("%d\n", sum);
    return 0;
}

