}

activity.solution:
#include <stdio.h>
#include <stdint.h>
int main(void) {
    uint16_t adc = 768;
    uint32_t mv = (uint32_t)adc * 5000u / 1024u;
    printf("%u\n", (unsigned)mv);
    return 0;
}
